mapper.select:
SELECT COUNT(DISTINCT user_id)
FROM activity_logs
WHERE action_time >= #{date}

mapper.update:
UPDATE users
SET
username = #{username},
email = #{email},
role = #{role}
WHERE id = #{id}

mapper.select:
SELECT u.*, COALESCE(ul.user_level, 1) as userLevel, a.admin_level as adminLevel FROM users u LEFT JOIN user_levels ul ON u.id = ul.user_id LEFT JOIN admins a ON u.id = a.user_id WHERE 1=1
AND (u.username LIKE CONCAT('%', #{keyword}, '%') OR u.email LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY u.id DESC LIMIT #{limit} OFFSET #{offset}
